// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    function setUp() public { c = new PENNY_BY_PENNY(); }

    function testFuzz_property(uint256 newVal) public {
        c.SetLogFile(address(this));
        c.Initialized();
        vm.prank(address(0xA11CE));
        bool ok;
        try c.SetMinSum(newVal) { ok = true; } catch { ok = false; }
        // Rule: after initialization, SetMinSum must always revert.
        // Reference: reverts for every input. Mutant: succeeds and writes MinSum.
        assertTrue(!ok && c.MinSum() == 0);
    }
}
